        c.beginPath();
        c.moveTo(-s / 2 - 2, -s / 2 - 2);
        c.lineTo(-s / 2 + d, -s / 2 - d - 2);
        c.lineTo(s / 2 + d + 2, -s / 2 - d - 2);
        c.lineTo(s / 2 + d + 2, s / 2 - d);
        c.lineTo(s / 2 + 2, s / 2 + 2);
        c.lineTo(-s / 2 - 2, s / 2 + 2);
        c.closePath();
        c.fill();
        c.fillStyle = "#e2b56a";
        c.beginPath();
        c.moveTo(-s / 2, -s / 2);
        c.lineTo(-s / 2 + d, -s / 2 - d);
        c.lineTo(s / 2 + d, -s / 2 - d);
        c.lineTo(s / 2, -s / 2);
        c.closePath();
        c.fill(); // top
