  // Aura: Showcase (Collector): a museum display — glass panes, spotlights from above, gold sparkle
  EXT_ITEM["aw-aura-showcase"] = { aura: "showcase" };
  EXT_AURA.showcase = ({ g, bloom, edge, hash, W, H }) => {
    let x0 = W,
      x1 = 0,
      y0 = H,
      y1 = 0;
    for (const [x, y] of edge) {
      if (x < x0) {
        x0 = x;
      }
      if (x > x1) {
        x1 = x;
      }
      if (y < y0) {
        y0 = y;
      }
      if (y > y1) {
        y1 = y;
      }
    }
    const L = Math.max(4, x0 - 22),
      R = Math.min(W - 4, x1 + 22),
      T = Math.max(4, y0 - 34),
      B = Math.min(H - 4, y1 + 12);
    g.save();
    // spotlight cones from above
    for (const [sx, tx] of [
      [L + 20, (x0 + x1) / 2 - 40],
      [R - 20, (x0 + x1) / 2 + 40],
    ]) {
      const gr = g.createLinearGradient(0, 0, 0, B);
      gr.addColorStop(0, "rgba(255,244,200,.55)");
      gr.addColorStop(1, "rgba(255,244,200,0)");
      g.fillStyle = gr;
      g.beginPath();
      g.moveTo(sx - 8, 0);
      g.lineTo(sx + 8, 0);
      g.lineTo(tx + 90, B);
      g.lineTo(tx - 90, B);
      g.closePath();
      g.fill();
    }
    bloom("#ffe9a8", 16, 0.35, 2);
    // glass case: faint panes, bright edges, diagonal reflections
    g.fillStyle = "rgba(210,240,255,.10)";
    g.fillRect(L, T, R - L, B - T);
    g.strokeStyle = "rgba(255,255,255,.85)";
    g.lineWidth = 2.5;
    g.strokeRect(L, T, R - L, B - T);
    g.strokeStyle = "rgba(200,170,90,.9)";
    g.lineWidth = 4;
    g.beginPath();
    g.moveTo(L - 2, B);
    g.lineTo(R + 2, B);
    g.moveTo(L - 2, T);
    g.lineTo(R + 2, T);
    g.stroke();
    g.strokeStyle = "rgba(255,255,255,.5)";
    g.lineCap = "round";
    for (const [ox, w] of [
      [0.12, 10],
      [0.2, 4],
      [0.78, 8],
      [0.85, 3],
    ]) {
      g.lineWidth = w;
      const xa = L + (R - L) * ox;
      g.beginPath();
      g.moveTo(xa, T + 8);
      g.lineTo(xa - 40, B - 8);
      g.stroke();
    }
    g.restore();
    for (let k = 0; k < 14; k++) {
      AWB_star4(
        g,
        L + hash(k, 1, 351) * (R - L),
        T + hash(k, 2, 351) * (B - T),
        2.5 + hash(k, 3, 351) * 5,
        "#fff6d0",
        "#ffcc33",
      );
    }
    return ["#fff2c0", 0.5];
  };

