  MOTIF.parquet = (g, w, h, p) => {
    g.strokeStyle = p.spk[0];
    g.globalAlpha = 0.45;
    g.lineWidth = 1.2;
    const s = w / 8; // herringbone wood blocks
    for (const [st, a, dy] of [
      [p.spk[0], 0.45, 0],
      ["#ffffff", 0.12, 1.5],
    ]) {
      g.strokeStyle = st;
      g.globalAlpha = a;
      for (let y = 0; y < h; y += s) {
        for (let x = 0; x < w; x += s * 2) {
          g.beginPath();
          g.moveTo(x, y + s + dy);
          g.lineTo(x + s, y + dy);
          g.lineTo(x + s * 2, y + s + dy);
          g.stroke();
        }
      }
    }
    g.globalAlpha = 1;
  }; // (a faint light edge too, so it shows on dark wood)
  MOTIF.zellige = (g, w, h, p, i) => {
    const s = w / 5;
    for (let y = 0; y < 5; y++) {
      for (let x = 0; x < 5; x++) {
        const cx = (x + 0.5) * s,
          cy = (y + 0.5) * s,
          r = s * 0.32;
        g.fillStyle = p.spk[(x + y + i) % p.spk.length];
        g.globalAlpha = 0.35; // small eight-point tile stars
        g.beginPath();
        for (let k = 0; k < 16; k++) {
          const a = (k / 16) * 6.283,
            rr = k % 2 ? r * 0.55 : r;
          g.lineTo(cx + Math.cos(a) * rr, cy + Math.sin(a) * rr);
        }
        g.closePath();
        g.fill();
      }
    }
    g.globalAlpha = 1;
  };
