      const r = btn.getBoundingClientRect();
      p.style.left = Math.max(8, Math.min(innerWidth - 294, r.left + r.width / 2 - 140)) + "px";
      p.style.top = Math.max(8, r.top - p.offsetHeight - 8) + "px";
