        g.quadraticCurveTo(L * 0.5, -L * 0.42, L + 1.5, 0);
        g.quadraticCurveTo(L * 0.5, L * 0.42, -1.5, 0);
        g.fill();
        g.fillStyle = cols[k % 5];
        g.beginPath();
        g.moveTo(0, 0);
        g.quadraticCurveTo(L * 0.5, -L * 0.35, L, 0);
        g.quadraticCurveTo(L * 0.5, L * 0.35, 0, 0);
        g.fill();
        g.strokeStyle = "rgba(220,255,170,.5)";
