        const [x0, y0] = edge[Math.floor(hash(k, 1, 171) * edge.length)];
        const x = x0 + (x0 - cx) * 0.3,
          y = y0 + (y0 - cy) * 0.3 - hash(k, 2, 171) * 20,
          r = 8 + hash(k, 3, 171) * 12;
        g.fillStyle = `rgba(235,235,240,${0.45 + hash(k, 4, 171) * 0.35})`;
