      g.save();
      g.strokeStyle = "rgba(0,0,0,.3)";
      g.lineWidth = 4;
      g.beginPath();
      g.moveTo(262, 152);
      g.lineTo(218, 176);
      g.stroke();
      g.restore();
      g.strokeStyle = lin(262, 150, 216, 174, [
        [0, "#fff0a0"],
        [1, "#a87a10"],
      ]);
      g.lineWidth = 3.5;
      g.lineCap = "round";
      g.beginPath();
      g.moveTo(262, 148);
      g.lineTo(216, 172);
      g.stroke(); // the pin
      for (let k = 0; k < 4; k++) {
        const x0 = 236 + k * 7,
          y0 = 162 - k * 2;
        g.strokeStyle = "#d4a52a";
        g.lineWidth = 0.8;
        g.beginPath();
        g.moveTo(x0, y0);
        g.lineTo(x0 - 2, y0 + 26 + k * 3);
        g.stroke(); // strands
        for (let j = 0; j < 3; j++) {
          sakuraPetal(g, x0 - (2 * (j + 1)) / 3, y0 + 9 + j * 8 + k, 4.5, 0.2 * j, j % 2 ? "#ffd1dc" : "#ff9ab5");
        }
      }
      g.save();
      g.filter = "blur(2px)";
      g.fillStyle = "rgba(0,0,0,.3)";
      g.beginPath();
      g.ellipse(262, 160, 24, 10, 0, 0, Math.PI * 2);
      g.fill();
      g.restore();
      sakuraFlower(g, 266, 142, 15, 0.2, "#ffc1d4");
