      gr.addColorStop(0, "rgba(" + col + "," + (0.55 - (k % 2) * 0.15) + ")");
      gr.addColorStop(1, "rgba(" + col + ",0)");
      g.fillStyle = gr;
      g.beginPath();
      g.moveTo(x - w / 2, cy);
      g.lineTo(x + w / 2, cy);
      g.lineTo(x + w / 2 + lean, top);
