      g.fill();
      g.strokeStyle = ink;
      g.lineWidth = 2.5;
      g.stroke();
      g.save();
      fin();
      g.clip();
      g.fillStyle = "rgba(255,255,255,.25)";
      g.beginPath();
      g.moveTo(250, 146);
      g.bezierCurveTo(262, 110, 274, 88, 296, 66);
      g.lineTo(290, 74);
      g.bezierCurveTo(272, 100, 264, 124, 258, 146);
      g.fill();
