      const g = c.getContext("2d");
      if (trophy) {
        g.drawImage(trophy, 10, 6, 100, 100);
      }
      g.font = "bold 58px TankTrouble, Arial";
      g.textAlign = "center";
      g.textBaseline = "middle";
      g.lineWidth = 7;
      g.strokeStyle = "#000";
      g.strokeText("?", 60, 52);
      g.fillStyle = locked ? "#bbb" : "#ffe14d";
