  const imgCache = {};
  function loadImg(url) {
    if (!imgCache[url]) {
      imgCache[url] = (String(url).startsWith("ttcl-art:") ? artSrc(url) : Promise.resolve(url)).then(
        (u) =>
          u &&
          new Promise((res) => {
            const i = new Image();
            i.onload = () => res(i);
            i.onerror = () => res(null);
            i.src = u;
          }),
      );
    }
    return imgCache[url];
  }
