  function freePreviewMemory() {
    clearTimeout(pvTimer);
    pvSeq++;
    for (const k in imgCache) {
      delete imgCache[k];
    }
    assetMapPromise = null;
    iconMap = null;
    for (const k in thumbCache) {
      delete thumbCache[k];
    }
    [bufA, bufB, bufO].forEach((b) => {
      b.width = 0;
      b.height = 0;
    });
    const cv = $("pv");
    cv.getContext("2d").clearRect(0, 0, cv.width, cv.height);
  }

  function keepOnScreen() {
    // Keep the whole panel on screen (it's 326px wide incl. border), not just a corner of it
    const w = (panel.offsetWidth || 326) + 8;
    GUI_POS.x = Math.max(0, Math.min(GUI_POS.x, window.innerWidth - w));
    GUI_POS.y = Math.max(0, Math.min(GUI_POS.y, window.innerHeight - 120));
    if (window.innerHeight - GUI_POS.y < 380) {
      GUI_POS.y = Math.max(0, window.innerHeight - 380);
    } // room for a usable panel below its top
    host.style.left = GUI_POS.x + "px";
    host.style.top = GUI_POS.y + "px";
    panel.style.maxHeight = Math.max(200, window.innerHeight - GUI_POS.y - 10) + "px"; // its bottom never goes off the screen (it scrolls inside instead)
  }

  let drag = null;
  function startDrag(e) {
    if (e.button !== 0 || (e.target.closest && e.target.closest("button"))) {
      return;
    }
    drag = { sx: e.clientX, sy: e.clientY, ox: GUI_POS.x, oy: GUI_POS.y };
    e.preventDefault();
  }
  $("hdr").addEventListener("mousedown", startDrag);
  window.addEventListener("mousemove", (e) => {
    if (!drag) {
      return;
    }
    const dx = e.clientX - drag.sx,
      dy = e.clientY - drag.sy;
    GUI_POS.x = drag.ox + dx;
    GUI_POS.y = drag.oy + dy;
    keepOnScreen(); // stops at the screen edges while dragging
  });
  window.addEventListener("mouseup", () => {
    if (!drag) {
      return;
    }
    drag = null;
    keepOnScreen();
    savePos();
  });
  window.addEventListener("resize", () => {
    if (host.isConnected) {
      keepOnScreen();
    }
  });

  // Saved data arrives from extension storage a moment after start-up
  function onDataLoaded() {
    keepOnScreen();
    if (panel.classList.contains("open")) {
      renderSources();
      renderPalette();
      renderList();
      syncPower();
      syncParty();
      syncDev();
    }
    if (SETTINGS.party) {
      partyRoll();
    } // party mode stays on across reloads
    const ids = Object.keys(PLAYER_COLOR_MAP).filter((id) => seenEarly.has(id));
    if (ids.length) {
      refreshSoon(ids);
    } // only tanks the game already drew before the data arrived (normally none: their details wait for it)
    warmLooks(); // your saved looks' pictures straight away, so no tank shows a stand-in picture first
    if (SETTINGS.laikaDog) {
      try {
        laikaDog();
      } catch {}
    } // Laika's dog sheet, ready before the menu's dog is made
    if (!hintSeen) {
      hintSeen = true;
      post({ type: "save", items: { tt_seen_hint: true } });
    }
    const go = () => setTimeout(tutAuto, 2500);
    if (document.body) {
      go();
    } else {
      document.addEventListener("DOMContentLoaded", go);
    }
  }

